{"alloy":{"configMap":{"content":"
discovery.kubernetes "local_pods" {
  role = "pod"
  selectors {
    role  = "pod"
    field = "spec.nodeName=" + coalesce(sys.env("NODE_NAME"), "")
  }
}

discovery.relabel "ebpf" {
  targets = discovery.kubernetes.local_pods.targets

  rule {
    source_labels = ["__meta_kubernetes_namespace"]
    target_label  = "namespace"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_name"]
    target_label  = "pod"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_container_name"]
    target_label  = "container"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_node_name"]
    target_label  = "node"
  }
  rule {
    source_labels = ["__meta_kubernetes_namespace", "__meta_kubernetes_pod_container_name"]
    separator     = "/"
    target_label  = "service_name"
  }
}

pyroscope.ebpf "default" {
  forward_to = [pyroscope.write.default.receiver]
  targets    = discovery.relabel.ebpf.output
}

pyroscope.write "default" {
  endpoint {
    url = "http://pyroscope.pyroscope.svc.cluster.local:4040"
  }
}
"},"extraEnv":[{"name":"OTEL_PROFILING_AGENT_MAP_SCALE_FACTOR","value":"1"},{"name":"NODE_NAME","valueFrom":{"fieldRef":{"fieldPath":"spec.nodeName"}}}],"resources":{"requests":{"cpu":"100m","memory":"768Mi"}},"securityContext":{"privileged":true,"readOnlyRootFilesystem":false,"runAsGroup":0,"runAsUser":0},"stabilityLevel":"experimental"},"controller":{"hostPID":true,"type":"daemonset","updateStrategy":{"rollingUpdate":{"maxUnavailable":1},"type":"RollingUpdate"}},"serviceMonitor":{"additionalLabels":{"release":"prometheus"},"enabled":true,"interval":"30s"}}
